+        assertThrows(IllegalArgumentException.class, () -> {
+            SequenceLayout oneByte = MemoryLayout.sequenceLayout(1, ValueLayout.JAVA_BYTE);
+            // 2^32
+            long n = 1L << 32;
+            // n * n -> overflow -> zero
+            oneByte.reshape(-1, n, n);
